CREATE TABLE IF NOT EXISTS public.portfolio_images (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  storage_path text NOT NULL UNIQUE,
  caption text,
  sort_order integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.portfolio_images ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Portfolio images are publicly readable" ON public.portfolio_images;
CREATE POLICY "Portfolio images are publicly readable"
  ON public.portfolio_images
  FOR SELECT
  TO anon, authenticated
  USING (true);

GRANT SELECT ON TABLE public.portfolio_images TO anon, authenticated;
GRANT ALL ON TABLE public.portfolio_images TO service_role;

